import { NAVIGATION_NAMES, navigationLabels, navigationDocument, navigationEntries, navigationRecord as record, navigationKind, navRead as read, navText as text, navNumber as number, navOrdinal as ordinal, navFlag as flag, navSet, navArray, navigationListPath, newNavigationItem, addNavigation, moveNavigation, setNavigationTabTarget, setCubeLayout, trimCubeSlots as trimSlots, cubeSlotCounts, validCubeRectangle, addCubeRectangle, removeCubeRectangle, setCubeMedia, canonicalNavigationImage, navigationLink, canonicalNavigationBlock, navigationColor, navigationCubeRects, type NavigationKind, type NavigationRecord, type CubeRectangle } from '@/utils/diyNavigationEditor';
const props=withDefaults(defineProps<{modelValue:string;editorKey:string;disabled?:boolean;pageId?:number;pagePublished?:boolean}>(),{disabled:false,pageId:0,pagePublished:false}),emit=defineEmits<{'update:modelValue':[value:string]}>(),auth=useAuthStore();
const names=NAVIGATION_NAMES,labels=navigationLabels,addKind=ref<NavigationKind>('headerSerch'),selected=ref(-1),itemIndex=ref(0),revision=ref(0),error=ref(''),previews=ref<Record<string,string>>({}),hotWords=ref<Array<{id:number;name:string}>>([]),hotLoading=ref(false),hotError=ref(''),previewLoading=ref(false),gridStart=ref<number|null>(null);
let alive=true,hotAbort:AbortController|null=null,previewAbort:AbortController|null=null,lastCommitted='';
const maxLength=Number.MAX_SAFE_INTEGER/2;
const actor=()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}:${getToken()}:${localStorage.getItem('admin_session')}`;
function editableNow(){return alive&&!props.disabled&&!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('dise.manage'));}
const canEdit=computed(()=>{void revision.value;return editableNow();}),canChooseMedia=computed(()=>canEdit.value&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('attachment.view')));
