const itemPath=computed<Array<string|number>>(()=>kind.value==='pictureCube'?['picStyle',layout.value===11?'docPicList':'picList']:kind.value?navigationListPath(kind.value):[]),items=computed(()=>navArray(block.value,itemPath.value)),item=computed(()=>record(items.value[itemIndex.value]));
const itemTitle=computed(()=>text(read(item.value,kind.value==='tabNav'?['text','val']:['info',0,'value']))),tabType=computed(()=>ordinal(read(item.value,['dataType','tabVal']),0,1)),tabDestination=computed(()=>{const target=record(read(item.value,[tabType.value===1?'classPage':'microPage']));return target?.id?`${text(target.name)} #${String(target.id)}`:'尚未选择真实目标';});
const currentImage=computed(()=>text(kind.value==='headerSerch'?read(block.value,['logoConfig','url']):kind.value==='menus'?item.value?.img:kind.value==='pictureCube'?item.value?.[layout.value===11?'img':'image']:'')),currentImagePreview=computed(()=>presentationPreviewForReference(currentImage.value,previews.value[canonicalPresentationReference(currentImage.value)])||presentationPreviewUrl(currentImage.value));
