const current=(s:ReturnType<typeof stamp>)=>alive&&canEdit.value&&s.actor===actor()&&s.editor===props.editorKey&&s.raw===props.modelValue&&s.revision===revision.value&&s.index===selected.value&&s.item===itemIndex.value;
function invalidate(clearCatalog=false){revision.value++;hotAbort?.abort();previewAbort?.abort();hotAbort=previewAbort=null;hotLoading.value=previewLoading.value=false;previews.value={};gridStart.value=null;if(clearCatalog){hotWords.value=[];hotError.value='';}}
