function textLimit(value:unknown,normal:number){return Math.max(normal,[...text(value)].length);}
function setText(path:Array<string|number>,value:unknown,normal:number){if(typeof value==='string'&&[...value].length<=textLimit(read(block.value,path),normal))setLeaf(path,value);}
function addItem(){if(!kind.value||kind.value==='pictureCube'||items.value.length>=(kind.value==='headerSerch'?20:100))return;const k=kind.value,path=itemPath.value,at=items.value.length;if(edit(row=>{const list=structuredClone(navArray(row,path));list.push(newNavigationItem(k));navSet(row,path,list);})){itemIndex.value=at;}}
function removeItem(){if(!kind.value||kind.value==='pictureCube'||itemIndex.value<0||itemIndex.value>=items.value.length)return;const at=itemIndex.value,path=itemPath.value;if(edit(row=>{const list=structuredClone(navArray(row,path));list.splice(at,1);navSet(row,path,list);})){itemIndex.value=Math.max(0,at-1);}}
function moveItem(direction:number){const to=itemIndex.value+direction;if(![-1,1].includes(direction)||to<0||to>=items.value.length)return;const from=itemIndex.value,path=itemPath.value;if(edit(row=>{const list=structuredClone(navArray(row,path));[list[from],list[to]]=[list[to],list[from]];navSet(row,path,list);})){itemIndex.value=to;}}
function setItemTitle(value:unknown){if(!kind.value||!item.value)return;setText([...itemPath.value,itemIndex.value,...(kind.value==='tabNav'?['text','val']:['info',0,'value'])],value,kind.value==='tabNav'?6:4);}
function setTabType(value:unknown){if(kind.value==='tabNav'&&item.value&&(value===0||value===1))setLeaf([...itemPath.value,itemIndex.value,'dataType','tabVal'],value);}
function setItemVisible(value:unknown){if(kind.value==='menus'&&item.value&&typeof value==='boolean')setLeaf([...itemPath.value,itemIndex.value,'show'],value);}
function setDuration(value:unknown){if(kind.value==='headerSerch'&&typeof value==='number'&&Number.isInteger(value)&&value>=1&&value<=100)setLeaf(['numConfig','val'],value);}
function chooseHotWord(value:unknown){if(kind.value==='headerSerch'&&item.value&&typeof value==='string'&&(value===text(item.value.val)||hotWords.value.some(word=>word.name===value)))setLeaf([...itemPath.value,itemIndex.value,'val'],value);}
async function loadHotWords(){if(!editableNow()||kind.value!=='headerSerch')return;hotAbort?.abort();const issued=stamp(),controller=new AbortController();hotAbort=controller;hotLoading.value=true;hotError.value='';try{const list=await apiDiyAuthorHotWords(controller.signal);if(current(issued)&&!controller.signal.aborted)hotWords.value=list;}catch(reason){if(current(issued))hotError.value=reason instanceof Error?reason.message:'平台热词读取失败';}finally{if(hotAbort===controller){hotAbort=null;hotLoading.value=false;}}}
function setImage(value:string){if(kind.value==='headerSerch')return edit(row=>navSet(row,['logoConfig','url'],canonicalNavigationImage(value)));if(kind.value==='menus'&&item.value)return edit(row=>navSet(row,[...itemPath.value,itemIndex.value,'img'],canonicalNavigationImage(value)));if(kind.value==='pictureCube'&&item.value)return edit(row=>setCubeMedia(row,itemIndex.value,'image',value));return false;}
const previewLease=computed(()=>{const issued=stamp();return()=>current(issued);});
const mediaSession=computed(()=>{const issued=stamp(),key=`${props.editorKey}:${revision.value}:${selected.value}:${itemIndex.value}`,actorAtIssue=actor(),editor=props.editorKey;return{key,choose:async(reference:string,signed:string)=>{if(!current(issued)||!canChooseMedia.value)return;const approved=presentationPreviewForReference(reference,signed),index=selected.value,slot=itemIndex.value;if(!setImage(reference))return;const expected=lastCommitted;await nextTick();if(alive&&canChooseMedia.value&&actor()===actorAtIssue&&props.editorKey===editor&&selected.value===index&&itemIndex.value===slot&&props.modelValue===expected&&canonicalPresentationReference(currentImage.value)===canonicalPresentationReference(reference)&&approved)previews.value={[canonicalPresentationReference(reference)]:approved};}};});
const linkSession=computed(()=>{const issued=stamp();return{key:`${props.editorKey}:${revision.value}:${selected.value}:${itemIndex.value}`,choose:(choice:DiyAuthorChoice)=>{if(!current(issued)||!choice||typeof choice.url!=='string')return;try{navigationLink(choice.url);}catch(reason){error.value=reason instanceof Error?reason.message:'链接无效';return;}if(kind.value==='tabNav'){if(!choice.selection||choice.selection.kind!==(tabType.value===1?'category':'micro'))return;edit(row=>setNavigationTabTarget(row,itemIndex.value,choice.selection!));}else if(kind.value==='pictureCube')edit(row=>setCubeMedia(row,itemIndex.value,'link',choice.url));else if(kind.value==='menus')setLeaf([...itemPath.value,itemIndex.value,'info',1,'value'],choice.url);else if(kind.value==='headerSerch')setLeaf(['linkConfig','value'],choice.url);}};});
function clearLink(){if(kind.value==='pictureCube')edit(row=>setCubeMedia(row,itemIndex.value,'link',''));else if(kind.value==='menus')setLeaf([...itemPath.value,itemIndex.value,'info',1,'value'],'');}
const cubeLabels=['上下两图','横排两图','横排三图','上二下一','上一下二','左一右二','左二右一','四宫格','上二下三','左一右三','单图','自定义'];
function layoutTiles(style:number){if(style===0)return[[0,0,1,.5],[0,.5,1,.5]];if(style===1||style===2){const n=style===1?2:3;return Array.from({length:n},(_,i)=>[i/n,0,1/n,1]);}if(style===10)return[[0,0,1,1]];if(style===11)return Array.from({length:16},(_,i)=>[(i%4)/4,Math.floor(i/4)/4,.25,.25]);return navigationCubeRects(style,[2,2,3,3,3,3,3,4,5,4,1,16][style]!);}
function trimCubeSlots(){if(edit(row=>trimSlots(row)))itemIndex.value=Math.min(itemIndex.value,cubeSlotCounts[layout.value]!-1);}
function changeCubeLayout(style:number){if(edit(row=>setCubeLayout(row,style)))itemIndex.value=0;}
const rectangleFields=[{key:'startX',label:'矩形左边距'},{key:'startY',label:'矩形上边距'},{key:'w',label:'矩形宽度'},{key:'h',label:'矩形高度'}];
const rectangleEntries=computed(()=>items.value.flatMap((r,index)=>{const rect=validCubeRectangle(read(r,['doc']));return rect?[{index,rect}]:[];}));
function rectangleStyle(r:CubeRectangle){return{left:`${r.startX/375*100}%`,top:`${r.startY/375*100}%`,width:`${r.w/375*100}%`,height:`${r.h/375*100}%`};}
function gridClick(cell:number){if(!canEdit.value||kind.value!=='pictureCube'||layout.value!==11)return;if(gridStart.value===null){gridStart.value=cell;return;}const first=gridStart.value,x=Math.min(first%4,cell%4),y=Math.min(Math.floor(first/4),Math.floor(cell/4)),rectangle={startX:x*93.75,startY:y*93.75,w:(Math.abs(first%4-cell%4)+1)*93.75,h:(Math.abs(Math.floor(first/4)-Math.floor(cell/4))+1)*93.75};let at=0;if(edit(row=>{at=addCubeRectangle(row,rectangle);}))itemIndex.value=at;gridStart.value=null;}
function setRectangle(key:string,value:unknown){if(kind.value!=='pictureCube'||layout.value!==11||!item.value||!rectangleFields.some(f=>f.key===key)||typeof value!=='number'||!Number.isFinite(value))return;const proposed={...record(item.value.doc),[key]:value};if(!validCubeRectangle(proposed)){error.value='矩形必须完整位于375×375画布内';return;}setLeaf([...itemPath.value,itemIndex.value,'doc',key],value);}
function deleteRectangle(){if(kind.value==='pictureCube'&&layout.value===11){const at=itemIndex.value;if(edit(row=>removeCubeRectangle(row,at)))itemIndex.value=Math.max(0,at-1);}}
const enumFields=computed(()=>{const f=(key:string,label:string,options:string[],fallback=0)=>({key,label,options,fallback}),k=kind.value;return[...(k==='headerSerch'?[f('styleConfig','搜索框布局',['logo＋搜索','标题＋搜索','仅搜索']),...(layout.value===2?[f('styleSearchConfig','搜索框样式',['居中胶囊','带底色按钮','文字按钮'])]:[])]:k==='tabNav'?[f('styleConfig','选项卡样式',['渐变下划线','圆点下划线','填充胶囊']),f('stickyConfig','选项卡吸顶',['开启','关闭'])]:k==='menus'?[f('menuStyleConfig','菜单显示',['图片与文字','仅图片','仅文字']),f('number','菜单列数',['3列','4列','5列']),f('showConfig','菜单翻页',['固定显示','分页显示']),...(ordinal(read(block.value,['showConfig','tabVal']),0,1)?[f('rowsNum','每页行数',['1行','2行','3行','4行'])]:[])]:[]),...(k!=='pictureCube'?[f('toneConfig','色调',['跟随主题','自定义'])]:[])];});
function setEnum(key:string,value:unknown){const field=enumFields.value.find(f=>f.key===key);if(field&&typeof value==='number'&&Number.isInteger(value)&&value>=0&&value<field.options.length)setLeaf([key,'tabVal'],value);}
interface ColourField{key:string;label:string;fallback:string;index:number}
const colourFields=computed(()=>{const f=(key:string,label:string,fallback:string,index=0):ColourField=>({key,label,fallback,index}),k=kind.value,custom=ordinal(read(block.value,['toneConfig','tabVal']),0,1)===1;return[...(k==='headerSerch'?[f('searchBoxColor','搜索框背景','#F5F5F5'),f('tipColor','搜索提示文字颜色','#CCCCCC'),f('hotWordsColor','热词文字颜色','#888'),...(layout.value===2&&custom?(ordinal(read(block.value,['styleSearchConfig','tabVal']))===1?[f('searchTxtColor','搜索按钮文字颜色','#fff'),f('searchBgColor','搜索按钮背景','#E93323')]:ordinal(read(block.value,['styleSearchConfig','tabVal']))===2?[f('searchColor','搜索操作文字颜色','#E93323')]:[]):[])]:k==='tabNav'&&custom?[...(layout.value===1?[f('decorateColor2','圆点颜色','#E93323')]:[f('decorateColor','选中渐变起始色','#E93323'),f('decorateColor','选中渐变结束色','#FF7931',1)]),f(layout.value===0?'textColor':layout.value===1?'textColor2':'textColor3','选中文字颜色',layout.value===0?'#333333':layout.value===1?'#E93323':'#fff')]:k==='menus'&&ordinal(read(block.value,['showConfig','tabVal']),0,1)&&custom?[f('pointerColor','选中翻页指示器颜色','#E93323'),f('pointerBgColor','未选中翻页指示器颜色','#DDDDDD')]:[]),...(k!=='pictureCube'?[f(k==='menus'?'bgColor':'moduleColor','组件渐变起始色','#fff'),f(k==='menus'?'bgColor':'moduleColor','组件渐变结束色','#fff',1)]:[]),f('bottomBgColor','外层背景',k==='pictureCube'?'#f5f5f5':'#fff')];});
function colour(f:ColourField){return navigationColor(read(block.value,[f.key,'color',f.index,'item']),f.fallback);}
function setColour(f:ColourField,value:unknown){if(typeof value==='string'&&colourFields.value.some(field=>field.key===f.key&&field.index===f.index)&&navigationColor(value,'')===value.trim())setLeaf([f.key,'color',f.index,'item'],value.trim());}
const lengthFields=computed(()=>[{key:'topConfig',label:'上内边距'},{key:'bottomConfig',label:'下内边距'},{key:'prConfig',label:'左右内边距'},...(kind.value!=='headerSerch'?[{key:'mbConfig',label:'页面上间距'}]:[]),...(kind.value==='pictureCube'?[{key:'imgConfig',label:'图片间隙'}]:[])]);
function setLength(key:string,value:unknown){if(lengthFields.value.some(f=>f.key===key)&&typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=maxLength)setLeaf([key,'val'],value);}
const radiusFields=computed(()=>kind.value==='pictureCube'?[{key:'filletImg',label:'图片圆角'}]:[{key:'fillet',label:'组件圆角'},...(kind.value==='menus'&&ordinal(read(block.value,['menuStyleConfig','tabVal']))!==2?[{key:'filletImg',label:'图片圆角'}]:[])]);
function setRadiusType(key:string,value:unknown){if(radiusFields.value.some(f=>f.key===key)&&(value===0||value===1))setLeaf([key,'type'],value);}
function radiusSeparate(key:string){const list=read(block.value,[key,'valList']);return flag(read(block.value,[key,'type']))&&Array.isArray(list)&&list.length===4?1:0;}
function radiusPath(key:string,index:number):Array<string|number>{const separate=radiusSeparate(key),order=kind.value==='headerSerch'||kind.value==='tabNav'?[0,1,2,3]:[0,1,3,2];return separate?[key,'valList',order[index]!, 'val']:[key,'val'];}
function radius(key:string,index:number){return number(read(block.value,radiusPath(key,index)));}
function setRadius(key:string,index:number,value:unknown){if(radiusFields.value.some(f=>f.key===key)&&typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=maxLength)setLeaf(radiusPath(key,index),value);}
function mediaPairs(row:NavigationRecord){const pairs:Array<{reference:string;preview:unknown}>=[];if(row.name==='headerSerch')pairs.push({reference:text(read(block.value,['logoConfig','url'])),preview:read(row,['logoConfig','url'])});else if(row.name==='menus')navArray(block.value,['menuConfig','list']).forEach((item,i)=>pairs.push({reference:text(read(item,['img'])),preview:read(row,['menuConfig','list',i,'img'])}));else if(row.name==='pictureCube')for(const [list,field]of[['picList','image'],['docPicList','img']]as const)navArray(block.value,['picStyle',list]).forEach((item,i)=>pairs.push({reference:text(read(item,[field])),preview:read(row,['picStyle',list,i,field])}));return pairs;}
async function loadSavedPreviews(){if(!editableNow()||!block.value||!props.pageId||!props.pagePublished)return;previewAbort?.abort();const issued=stamp(),controller=new AbortController(),id=props.pageId,expected=JSON.stringify(canonicalNavigationBlock(block.value));previewAbort=controller;previewLoading.value=true;previews.value={};error.value='';try{const response=await fetch(`/api/diy/get_diy/${id}`,{credentials:'omit',cache:'no-store',signal:controller.signal}),body=record(await response.json()),data=record(body?.data);if(!current(issued)||props.pageId!==id||!props.pagePublished||controller.signal.aborted)return;if(!response.ok||body?.status!==200||!Array.isArray(data?.value))throw Error('公开导航预览暂不可用');const found=data.value.map(record).find(row=>row&&JSON.stringify(canonicalNavigationBlock(row))===expected);if(!found)throw Error('当前导航与已发布内容不同，请保存后再读取');const next:Record<string,string>={};for(const pair of mediaPairs(found)){const approved=presentationPreviewForReference(pair.reference,pair.preview);if(approved)next[canonicalPresentationReference(pair.reference)]=approved;}previews.value=next;}catch(reason){if(current(issued))error.value=reason instanceof Error?reason.message:'导航图片预览失败';}finally{if(previewAbort===controller){previewAbort=null;previewLoading.value=false;}}}
</script>
